void hr_font_funcs_destroy(struct hr_font_funcs_t *ffuncs);

/**
 * Attaches user data to a set of font callbacks.
 *
 * # Safety
 *
 * `ffuncs` must be `NULL` or live, and `key` must outlive it.
 */
hr_bool_t hr_font_funcs_set_user_data(struct hr_font_funcs_t *ffuncs,
                                      const struct hr_user_data_key_t *key,
                                      void *data,
                                      hr_destroy_func_t destroy,
                                      hr_bool_t replace);

/**
 * Retrieves user data attached to a set of font callbacks.
 *
 * # Safety
 *
 * `ffuncs` must be `NULL` or live.
 */
void *hr_font_funcs_get_user_data(struct hr_font_funcs_t *ffuncs,
                                  const struct hr_user_data_key_t *key);

/**
 * Marks a set of font callbacks immutable.
 *
 * # Safety
 *
 * `ffuncs` must be `NULL` or live.
 */
void hr_font_funcs_make_immutable(struct hr_font_funcs_t *ffuncs);

/**
 * Returns whether a set of font callbacks has been marked immutable.
 *
 * # Safety
 *
 * `ffuncs` must be `NULL` or live.
 */
